  section.insertAdjacentHTML("beforeend", `<details><summary>Estados iniciais dos blocos dinâmicos C e H</summary><p class="muted">Os estados são lidos na ordem da realização canônica da função de transferência. Deixe vazio para iniciar em zero.</p><label class="field">Estados iniciais de C<textarea id="controllerX0" rows="2" style="width:100%">${project.controllerInitialState?.join(", ") ?? ""}</textarea></label><label class="field">Estados iniciais de H<textarea id="sensorX0" rows="2" style="width:100%">${project.sensorInitialState?.join(", ") ?? ""}</textarea></label></details>`);
