  side.insertBefore(section,document.getElementById("models"));
  (section.querySelector<HTMLTextAreaElement>("#lqgStateWeight")!).value=project.lqgWeights?.state?JSON.stringify(project.lqgWeights.state):"";
  (section.querySelector<HTMLTextAreaElement>("#lqgProcessNoise")!).value=project.lqgWeights?.processNoise?JSON.stringify(project.lqgWeights.processNoise):"";
  (section.querySelector<HTMLInputElement>("#lqgControlWeight")!).value=String(project.lqgWeights?.control??1);
