function normalizedRootRepresentation(roots:{re:number;im:number}[],format:"timeConstant"|"naturalFrequency"):{scale:number;factors:string[]}{const remaining=roots.map(root=>({...root})),factors:string[]=[];let scale=1;while(remaining.length){const root=remaining.shift()!;if(Math.abs(root.im)>1e-9){const pairIndex=remaining.findIndex(candidate=>Math.abs(candidate.re-root.re)<1e-7&&Math.abs(candidate.im+root.im)<1e-7);if(pairIndex<0){factors.push(`(s − (${fmtRoot(root)}))`);continue}remaining.splice(pairIndex,1);const wn=Math.hypot(root.re,root.im),zeta=-root.re/wn;if(format==="timeConstant"){const tau=1/wn;scale*=wn*wn;factors.push(`((τs)^2 + ${ (2*zeta).toPrecision(5)}τs + 1), τ=${tau.toPrecision(5)}`)}else{scale*=wn*wn;factors.push(`((s/${wn.toPrecision(5)})^2 + ${(2*zeta).toPrecision(5)}(s/${wn.toPrecision(5)}) + 1)`)}continue}if(Math.abs(root.re)<1e-12){factors.push("s");continue}const tau=-1/root.re;scale*=(-root.re);factors.push(format==="timeConstant"?`(1 + ${tau.toPrecision(5)}s)`:`(1 + s/${(-root.re).toPrecision(5)})`)}return {scale,factors}}
