  const rate=(root:{re:number;im:number})=>domain==="continuous"?-root.re:root.re>0&&root.re<1?-Math.log(root.re)/sampleTime:Number.NaN;
  for(let zi=0;zi<zs.length;zi++){const zero=zs[zi]!;if(usedZ.has(zi)||Math.abs(zero.im)>1e-8)continue;const wz=rate(zero);if(!(wz>0&&Number.isFinite(wz)))continue;let best=-1,error=Infinity;for(let pi=0;pi<ps.length;pi++){const pole=ps[pi]!;if(usedP.has(pi)||Math.abs(pole.im)>1e-8)continue;const wp=rate(pole);if(!(wp>0&&Number.isFinite(wp)))continue;const mismatch=Math.abs(Math.log(wp/wz));if(mismatch>1e-7&&mismatch<error){best=pi;error=mismatch}}if(best>=0){const pole=ps[best]!,wp=rate(pole);groups.push({kind:wz<wp?"lead":"lag",zero:[zi],pole:[best],zeroRoot:zero,poleRoot:pole});usedZ.add(zi);usedP.add(best)}}
