function controlDesignMatlabScript(value:ControlDesignProject,responses:{name:string;model:ReturnType<typeof tf>}[]=[]):string{
  const ts=Number(value.sampleTime),domain=value.domain,architecture=value.architecture??"forward-controller",variable=domain==="discrete"?`, ${ts.toPrecision(15)}, 'Variable', 'z'`:"",lines=["% Modelos exportados do LasecSimul SisoTools.",`% Arquitetura: ${architecture}.`,`% Os coeficientes discretos usam potencias decrescentes de z.`,`ControlDesignerDomain = '${domain}';`,`ControlDesignerArchitecture = '${architecture}';`,domain==="discrete"?`Ts = ${ts.toPrecision(15)};`:"",""];
  const emit=(name:string,model:{num:string;den:string}|undefined)=>{const m=model??{num:"1",den:"1"};lines.push(`${name} = tf(${matlabArray(m.num)}, ${matlabArray(m.den)}${variable});`)};
  emit("F",value.F);emit("C",value.C);
  if(value.plantStateSpace){const ss=value.plantStateSpace,matrix=(rows:number[][])=>`[${rows.map(row=>row.map(n=>Number(n).toPrecision(15)).join(" ")).join("; ")}]`,vector=(items:number[])=>`[${items.map(n=>Number(n).toPrecision(15)).join(" ")}]`;lines.push(`G = ss(${matrix(ss.A)}, ${vector(ss.B)}, ${vector(ss.C)}, ${Number(ss.D).toPrecision(15)}${domain==="discrete"?", Ts":""});`);const x0=value.plantInitialState;if(x0?.length)lines.push(`x0 = ${vector(x0)}; % condicao inicial da planta para initial(G, x0)`)}else emit("G",value.G);
  if(value.plantFrd){const frequencies=`[${value.plantFrd.frequencyRadPerSecond.map(n=>Number(n).toPrecision(15)).join(" ")}]`,real=`[${value.plantFrd.response.map(item=>Number(item.re).toPrecision(15)).join(" ")}]`,imag=`[${value.plantFrd.response.map(item=>Number(item.im).toPrecision(15)).join(" ")}]`,sampleTime=domain==="discrete"?`, ${ts.toPrecision(15)}`:"";lines.push(`FRDPlant = frd(complex(${real}, ${imag}), ${frequencies}${sampleTime}, 'FrequencyUnit', 'rad/s');`)}
  emit("H",value.H);emit("C2",value.C2);emit("H2",value.H2);
  if((value.plantDelaySeconds??0)>0)lines.push(`G.InputDelay = ${(domain==="discrete"?Math.round(Number(value.plantDelaySeconds)/ts):Number(value.plantDelaySeconds)).toPrecision(15)};`);
  const variants=value.plantVariants??[];
  if(variants.length){lines.push("","% Variantes SISO como arrays de modelos para analise multimodelo.","Gmodels(:,:,1) = ss(G);","Hmodels(:,:,1) = ss(H);");for(const [index,variant] of variants.entries()){const suffix=index+1;if(variant.stateSpace){const ss=variant.stateSpace,matrix=(rows:number[][])=>`[${rows.map(row=>row.map(n=>Number(n).toPrecision(15)).join(" ")).join("; ")}]`,vector=(items:number[])=>`[${items.map(n=>Number(n).toPrecision(15)).join(" ")}]`;lines.push(`Gv${suffix} = ss(${matrix(ss.A)}, ${vector(ss.B)}, ${vector(ss.C)}, ${Number(ss.D).toPrecision(15)}${domain==="discrete"?", Ts":""});`)}else emit(`Gv${suffix}`,variant.plant);lines.push(`Gmodels(:,:,${suffix+1}) = ss(Gv${suffix});`);if(variant.sensor)emit(`Hv${suffix}`,variant.sensor);else lines.push(`Hv${suffix} = H;`);lines.push(`Hmodels(:,:,${suffix+1}) = ss(Hv${suffix});`)}if(architecture==="nested-inner-forward"){lines.push("H1models(:,:,1) = ss(H2);",`G2models(:,:,1) = ss(tf(1,1${domain==="discrete"?", Ts":""}));`);for(let index=0;index<variants.length;index++)lines.push(`H1models(:,:,${index+2}) = ss(H2);`,`G2models(:,:,${index+2}) = ss(tf(1,1${domain==="discrete"?", Ts":""}));`)}}
  const gModel=variants.length?"Gmodels":"G",hModel=variants.length?"Hmodels":"H";
  if(architecture==="forward-controller"){lines.push("L = C*G*H;","S = feedback(1, L);","T = feedback(L, 1);","Y_R = F*C*G*S;","U_R = F*C*S;")}
  const config=architecture==="forward-controller"?1:architecture==="feedback-controller"?2:architecture==="feedforward-disturbance"?3:architecture==="nested-inner-feedback"?4:architecture==="imc"?5:6;
  lines.push("",`% Recria a arquitetura MATLAB ${config} com seus modelos ativos.`,`s = sisoinit(${config});`);
  if(config<=3)lines.push(`s.G.Value = ${gModel};`,"s.C.Value = C;",`s.H.Value = ${hModel};`,"s.F.Value = F;");
  else if(config===4)lines.push(`s.G.Value = ${gModel};`,"s.C1.Value = C;","s.C2.Value = C2;",`s.H.Value = ${hModel}; % sensor da malha externa`);
  else if(config===5)lines.push(`s.G1.Value = ${gModel};`,`s.G2.Value = ${hModel}; % modelo preditivo`,"s.Gd.Value = C2; % modelo de perturbacao","s.C.Value = C;","s.F.Value = F;");
  else lines.push(`s.G1.Value = ${gModel};`,variants.length?"s.G2.Value = G2models;":"s.G2.Value = tf(1,1"+(domain==="discrete"?", Ts":"")+");","s.C1.Value = C;","s.C2.Value = C2;",`s.H1.Value = ${variants.length?"H1models":"H2"}; % sensor da malha interna`,`s.H2.Value = ${hModel}; % sensor da malha externa`,"s.F.Value = F;");
  if(responses.length){const vector=(items:number[])=>`[${items.map(n=>Number(n).toPrecision(15)).join(" ")}]`,used=new Set<string>();lines.push("","% Respostas salvas no Data Browser, exportadas como modelos I/O.");for(const response of responses){let identifier=`IOTransfer_${response.name.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zA-Z0-9_]/g,"_")}`;if(!/^[A-Za-z]/.test(identifier))identifier=`IOTransfer_${identifier}`;const base=identifier;let suffix=2;while(used.has(identifier))identifier=`${base}_${suffix++}`;used.add(identifier);lines.push(`${identifier} = tf(${vector(response.model.num)}, ${vector(response.model.den)}${variable});`)}}
  if(value.plantFrd&&architecture==="forward-controller")lines.push("% Abre os editores de malha aberta com os dados FRD medidos diretamente.","controlSystemDesigner({'bode', 'nichols'}, FRDPlant, C, H, F);");else lines.push("controlSystemDesigner(s);");return lines.filter(Boolean).join("\n")+"\n";
}
function download(text:string,name:string,type="application/json"){const a=document.createElement("a"),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.addEventListener("message",e=>{if(e.data.type==="applyCancelled")document.getElementById("saved")!.textContent="Aplicação cancelada";if(e.data.type==="bindingRefreshError"){showError(e.data.message||"Não foi possível atualizar o vínculo")}if(e.data.type==="applyError"){showError(e.data.message||"Falha ao aplicar controlador")}if(e.data.type==="importedModel"){try{const m=e.data.model,target=(e.data.target??"G") as "F"|"C"|"G"|"H",modelDomain=m.domain??"continuous";if(e.data.adoptDomain&&target==="G"){if(modelDomain==="discrete"&&(!(Number.isFinite(m.sampleTime)&&m.sampleTime>0)))throw new Error("Identified discrete model must include a valid Ts.");project.domain=modelDomain;if(modelDomain==="discrete")project.sampleTime=m.sampleTime;}if(m.den.length>1&&modelDomain!==project.domain)throw new Error("Imported dynamic model domain must match the project. Convert it explicitly first.");if(modelDomain==="discrete"&&m.den.length>1&&Math.abs(m.sampleTime-project.sampleTime)>1e-12)throw new Error("Imported model Ts must match the project Ts.");project[target]={num:m.num.join(", "),den:m.den.join(", ")};if(target==="F"){filterGainBase=structuredClone(project.F);const slider=document.getElementById("filterGain") as HTMLInputElement|null;if(slider)slider.value="0"}if(target==="G"){delete project.plantFrd;delete project.plantDelaySeconds;project.plantDomain=modelDomain;if(m.stateSpace)project.plantStateSpace=m.stateSpace;else delete project.plantStateSpace;if(m.stateSpace?.x0)project.plantInitialState=[...m.stateSpace.x0];else delete project.plantInitialState;}const bindings={...project.sourceBindings};if(m.binding)bindings[target]={...m.binding,modelSignature:modelFingerprint(project[target])};else delete bindings[target];project.sourceBindings=bindings;if(e.data.adoptDomain)renderShell();if(target==="C"){gainBase=structuredClone(project.C);(document.getElementById("gain") as HTMLInputElement).value="0"}const ni=document.querySelector<HTMLInputElement>(`[data-model="${target}"][data-part="num"]`),di=document.querySelector<HTMLInputElement>(`[data-model="${target}"][data-part="den"]`);if(ni)ni.value=project[target].num;if(di)di.value=project[target].den;if(target==="C")renderControllerPz();renderBindings();markDirty();analyze();showError("");document.getElementById("saved")!.textContent=`Modelo ${target} importado: ${m.label}${m.binding?"":" (sem vínculo individual)"}`}catch(err){showError(err)}}if(e.data.type==="bindingStatus"){bindingStatuses=e.data.statuses??{};renderBindings()}if(e.data.type==="applyCompleted"){try{project=normalize(e.data.project);renderShell();analyze();dirty=false;document.getElementById("saved")!.textContent=e.data.target==="G"?"Planta A/B/C/D aplicada e vínculo salvo":"C aplicado e vínculo salvo"}catch(err){showError(err)}}if(e.data.type==="init"){try{project=normalize(e.data.project);renderShell();analyze();dirty=false}catch(err){showError(err)}}if(e.data.type==="saved"){dirty=false;document.getElementById("saved")!.textContent="Salvo no projeto; salve o .lsproj"}});window.addEventListener("beforeunload",()=>{if(dirty)vscode?.postMessage({type:"save",project})});renderShell();vscode?.postMessage({type:"ready"});
